import subprocess, glob, re, zipfile, os, shutil

base = os.path.abspath(os.path.join(os.getcwd(), '..'))

def extract_text(path):
    if path.endswith('.pdf'):
        try:
            return subprocess.check_output(['pdftotext','-f','1','-l','1',path,'-'], text=True, errors='ignore')
        except Exception:
            return ''
    elif path.endswith('.docx'):
        try:
            with zipfile.ZipFile(path) as z:
                xml = z.read('word/document.xml').decode('utf-8', errors='ignore')
            return re.sub('<[^<]+?>',' ',xml)
        except Exception:
            return ''
    elif path.endswith('.pptx'):
        try:
            text_parts=[]
            with zipfile.ZipFile(path) as z:
                for name in z.namelist():
                    if name.startswith('ppt/slides/slide') and name.endswith('.xml'):
                        xml = z.read(name).decode('utf-8', errors='ignore')
                        text_parts.append(re.sub('<[^<]+?>',' ',xml))
            return ' '.join(text_parts)
        except Exception:
            return ''
    return ''

black_hole_re = re.compile(r'black hole|black-hole|event horizon|hawking|kerr|schwarzschild|singularity', re.I)
DNA_re = re.compile(r'\b(dna|genome|genetic|gene|chromosome|nucleotide|genomics|rna|protein|sequencing)\b', re.I)
music_re = re.compile(r'\b(music|musical|composer|symphony|opera|baroque|classical|jazz|song|musicology|melody|rhythm|pop|popular music|rock|hip hop)\b', re.I)
LLM_re = re.compile(r'large language model|language model|\bllm\b|\bgpt\b|chatgpt|transformer|instruction tuning|prompt|in-context', re.I)
trapped_re = re.compile(r'trapped ion|ion trap|ion-trap|trapped-ion', re.I)
qc_re = re.compile(r'quantum computing|quantum computer|quantum information|qubit|quantum gate|quantum logic|quantum simulation|quantum processor', re.I)

files = sorted(glob.glob('*.pdf') + glob.glob('*.docx') + glob.glob('*.pptx'))
from collections import Counter
counts = Counter()

for f in files:
    text = extract_text(f)
    t = text.lower()
    if black_hole_re.search(text):
        cat = 'black_hole'
    elif DNA_re.search(text):
        cat = 'DNA'
    elif music_re.search(text):
        cat = 'music_history'
    elif LLM_re.search(text):
        cat = 'LLM'
    elif trapped_re.search(text) or qc_re.search(text) or 'quantum' in t:
        cat = 'trapped_ion_and_qc'
    else:
        cat = 'trapped_ion_and_qc'

    dest = os.path.join(base, cat, os.path.basename(f))
    shutil.move(f, dest)
    counts[cat] += 1

print('Moved counts:', counts)
